// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));
        vm.assume(caddress != address(c));
        for (uint i = 0; i < _tos.length; i++) {
            vm.assume(_tos[i] != address(0));
            vm.assume(_tos[i] != address(c));
        }
        bool ok = false;
        (bool success, bytes memory data) = address(c).call(abi.encodeWithSelector(airdrop.transfer.selector, from, caddress, _tos, v));
        if (success) {
            ok = abi.decode(data, (bool));
        }
        assertTrue(ok == true);
    }
}
